import { createRequire } from "node:module";
import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import type { CallResult, PayPalPort, PayoutItemInput } from "./port.ts";

const require = createRequire(import.meta.url);
const { PayPalAgentToolkit } = require("@paypal/agent-toolkit/openai");
// PayPal's Server SDK, generated by APIMatic from PayPal's OpenAPI definitions. Purser uses
// its OrdersController for every Orders v2 call it makes outside the Agent Toolkit
// (create for non-USD events, get for reconciliation, capture on the buyer's return):
// typed request models, client-credentials OAuth, PayPal-Request-Id and Prefer headers.
const ServerSdk = require("@paypal/paypal-server-sdk");
export const SERVER_SDK_VERSION: string = JSON.parse(
  readFileSync(join(dirname(require.resolve("@paypal/paypal-server-sdk")), "..", "..", "package.json"), "utf8"),
).version;
const SANDBOX_BASE = "https://api-m.sandbox.paypal.com";
// The package does not export its package.json, so read it next to the entry point.
export const TOOLKIT_VERSION: string = JSON.parse(
  readFileSync(join(dirname(require.resolve("@paypal/agent-toolkit/openai")), "..", "package.json"), "utf8"),
).version;

/** The only Agent Toolkit actions Purser enables. Everything else stays off. */
export const TOOLKIT_ACTIONS = {
  orders: { create: true, get: true, capture: true },
  invoices: { create: true, get: true, send: true, sendReminder: true, cancel: true },
  payments: { createRefund: true, getRefunds: true },
  transactions: { list: true },
};

/**
 * PayPal puts the machine-readable reason (INSTRUMENT_DECLINED, ORDER_ALREADY_CAPTURED...)
 * in details[].issue and a generic sentence in message; keep both.
 */
export function describeError(data: any, status: number): string {
  const issues = Array.isArray(data?.details) ? data.details.map((d: any) => d?.issue).filter(Boolean) : [];
  const msg = data?.message ?? data?.error_description ?? (typeof data?.error === "string" ? data.error : undefined) ?? `HTTP ${status}`;
  return issues.length ? `${issues.join(", ")}: ${msg}` : String(msg);
}

export interface LiveConfig {
  clientId: string;
  clientSecret: string;
  webhookId?: string;
  base?: string;
  timeoutMs?: number;
}

export class LivePayPal implements PayPalPort {
  readonly mode = "sandbox" as const;
  private token?: { value: string; expires: number };
  private toolkit: any;
  private base: string;

  private cfg: LiveConfig;
  private timeoutMs: number;
  constructor(cfg: LiveConfig) {
    this.cfg = cfg;
    this.timeoutMs = cfg.timeoutMs ?? 30_000;
    this.base = cfg.base ?? "https://api-m.sandbox.paypal.com";
    this.toolkit = new PayPalAgentToolkit({
      clientId: cfg.clientId,
      clientSecret: cfg.clientSecret,
      // The toolkit defaults to PRODUCTION unless sandbox is set explicitly.
      configuration: { actions: TOOLKIT_ACTIONS, context: { sandbox: true, source: "purser" } },
    });
  }

  describe() {
    return { mode: "PayPal sandbox", base: this.base, toolkitVersion: TOOLKIT_VERSION, serverSdkVersion: SERVER_SDK_VERSION };
  }

  // ---- Orders v2 through the PayPal Server SDK (APIMatic) ----------------------

  private sdkOrders?: any;

  /** The SDK's OrdersController, built lazily; rebuilt after a 401 so it fetches a new token. */
  private orders(): any {
    if (this.sdkOrders) return this.sdkOrders;
    const config: Record<string, unknown> = {
      environment: ServerSdk.Environment.Sandbox,
      timeout: this.timeoutMs,
      clientCredentialsAuthCredentials: { oAuthClientId: this.cfg.clientId, oAuthClientSecret: this.cfg.clientSecret },
    };
    // The SDK only knows PayPal's own hosts. A different base (a local mock in the tests, an
    // unreachable host in the failure drill) is reached by rewriting the host in front of
    // the SDK's own HTTP adapter, so the request itself is still built by the SDK.
    if (this.base !== SANDBOX_BASE) {
      const axios = createRequire(require.resolve("@apimatic/axios-client-adapter"))("axios");
      const http = axios.getAdapter("http");
      const base = this.base;
      config.unstable_httpClientOptions = {
        adapter: (c: any) => http({ ...c, url: String(c.url).replace(SANDBOX_BASE, base) }),
      };
    }
    this.sdkOrders = new ServerSdk.OrdersController(new ServerSdk.Client(config));
    return this.sdkOrders;
  }

  /**
   * Runs one OrdersController call and returns the same CallResult the REST helper does.
   * The ledger reads PayPal's wire format (snake_case), so data is the raw response body;
   * an expired or revoked token gets one retry with a fresh client and the same request id.
   */
  private async viaSdk(call: (orders: any) => Promise<any>, retried = false): Promise<CallResult> {
    let res: any;
    try {
      res = await call(this.orders());
    } catch (e: any) {
      if (!(e instanceof ServerSdk.ApiError)) throw e; // network failure: the treasury records it
      if (e.statusCode === 401 && !retried) {
        this.sdkOrders = undefined;
        return this.viaSdk(call, true);
      }
      const data = parseBody(e.body);
      return { ok: false, status: e.statusCode, data, debugId: header(e.headers, "paypal-debug-id"), error: describeError(data, e.statusCode) };
    }
    return { ok: true, status: res.statusCode, data: parseBody(res.body), debugId: header(res.headers, "paypal-debug-id") };
  }

  private async accessToken(): Promise<string> {
    if (this.token && this.token.expires > Date.now() + 60_000) return this.token.value;
    const auth = Buffer.from(`${this.cfg.clientId}:${this.cfg.clientSecret}`).toString("base64");
    const res = await fetch(`${this.base}/v1/oauth2/token`, {
      method: "POST",
      signal: AbortSignal.timeout(this.timeoutMs),
      headers: { Authorization: `Basic ${auth}`, "Content-Type": "application/x-www-form-urlencoded" },
      body: "grant_type=client_credentials",
    });
    if (!res.ok) throw new Error(`PayPal OAuth failed with HTTP ${res.status}`);
    const j: any = await res.json();
    this.token = { value: j.access_token, expires: Date.now() + Number(j.expires_in ?? 3000) * 1000 };
    return this.token.value;
  }

  /** Forgets the cached OAuth token (used when PayPal says it expired or was revoked). */
  invalidateToken() {
    this.token = undefined;
  }

  private async rest(method: string, path: string, body?: unknown, requestId?: string, retried = false): Promise<CallResult> {
    const headers: Record<string, string> = {
      Authorization: `Bearer ${await this.accessToken()}`,
      "Content-Type": "application/json",
      Prefer: "return=representation",
    };
    if (requestId) headers["PayPal-Request-Id"] = requestId;
    const res = await fetch(`${this.base}${path}`, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: AbortSignal.timeout(this.timeoutMs),
    });
    // An access token can expire or be revoked before our clock says so: fetch a
    // new one and retry once. The PayPal-Request-Id keeps a retried POST idempotent.
    if (res.status === 401 && !retried) {
      await res.arrayBuffer().catch(() => undefined);
      this.invalidateToken();
      return this.rest(method, path, body, requestId, true);
    }
    const text = await res.text();
    let data: any = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      data = { raw: text.slice(0, 500) };
    }
    const debugId = res.headers.get("paypal-debug-id") ?? undefined;
    return {
      ok: res.ok,
      status: res.status,
      data,
      debugId,
      error: res.ok ? undefined : describeError(data, res.status),
    };
  }

  async callTool(name: string, args: Record<string, unknown>): Promise<CallResult> {
    const msg = await this.toolkit.handleToolCall({
      id: `call_${randomUUID()}`,
      type: "function",
      function: { name, arguments: JSON.stringify(args) },
    });
    const content: string | undefined = msg?.content;
    if (content === undefined || content === "") return { ok: true, status: 204, data: null };
    let data: any;
    try {
      data = JSON.parse(content);
    } catch {
      data = { raw: content };
    }
    // The toolkit reports failures as JSON rather than throwing.
    const err = data?.error ?? (data?.ok === false ? data : undefined);
    if (err) return { ok: false, status: Number(err.status ?? 400), data, error: describeError(err, Number(err.status ?? 400)).slice(0, 400) };
    if (data?.status === "error") return { ok: false, status: 400, data, error: "Capture failed" };
    return { ok: true, status: 200, data };
  }

  /**
   * Orders v2 capture through the Server SDK. `mockResponse` is PayPal's negative-testing
   * header (sandbox only), used by the live end-to-end drill to provoke a real decline.
   */
  captureOrder(orderId: string, requestId: string, mockResponse?: string) {
    return this.viaSdk((o) =>
      o.captureOrder({ id: orderId, paypalRequestId: requestId, prefer: "return=representation", paypalMockResponse: mockResponse, body: {} }),
    );
  }

  getOrder(orderId: string) {
    return this.viaSdk((o) => o.getOrder({ id: orderId }));
  }

  /** Orders v2 create through the Server SDK, for currencies the toolkit's create_order does not accept. */
  createOrderRest(body: unknown, requestId: string) {
    return this.viaSdk((o) => o.createOrder({ body: toSdkModel(body), paypalRequestId: requestId, prefer: "return=representation" }));
  }

  createPayout(batchId: string, subject: string, items: PayoutItemInput[]) {
    return this.rest(
      "POST",
      "/v1/payments/payouts",
      {
        sender_batch_header: { sender_batch_id: batchId, email_subject: subject, email_message: subject },
        items: items.map((i) => ({
          recipient_type: "EMAIL",
          amount: { value: i.value, currency: i.currency },
          receiver: i.email,
          note: i.note,
          sender_item_id: i.senderItemId,
        })),
      },
      batchId,
    );
  }

  getPayoutBatch(batchId: string) {
    return this.rest("GET", `/v1/payments/payouts/${encodeURIComponent(batchId)}`);
  }

  async verifyWebhook(h: Record<string, string | undefined>, body: any) {
    if (!this.cfg.webhookId) return "NO_WEBHOOK_ID" as const;
    const r = await this.rest("POST", "/v1/notifications/verify-webhook-signature", {
      auth_algo: h["paypal-auth-algo"],
      cert_url: h["paypal-cert-url"],
      transmission_id: h["paypal-transmission-id"],
      transmission_sig: h["paypal-transmission-sig"],
      transmission_time: h["paypal-transmission-time"],
      webhook_id: this.cfg.webhookId,
      webhook_event: body,
    });
    return r.ok && r.data?.verification_status === "SUCCESS" ? ("SUCCESS" as const) : ("FAILURE" as const);
  }
}

/** PayPal's JSON is snake_case; the SDK's models are the same fields in camelCase. */
export function toSdkModel(v: unknown): any {
  if (Array.isArray(v)) return v.map(toSdkModel);
  if (v === null || typeof v !== "object") return v;
  return Object.fromEntries(Object.entries(v).map(([k, x]) => [k.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase()), toSdkModel(x)]));
}

function parseBody(body: unknown): any {
  if (typeof body !== "string" || body === "") return null;
  try {
    return JSON.parse(body);
  } catch {
    return { raw: body.slice(0, 500) };
  }
}

function header(h: Record<string, string> | undefined, name: string): string | undefined {
  if (!h) return undefined;
  const k = Object.keys(h).find((x) => x.toLowerCase() === name);
  return k ? h[k] : undefined;
}
